    "titleEn": "One man in a boat",
    "titleZh": "独坐孤舟",
    "unitGroup": "第一单元 (第1-24课) 动名词与兴趣爱好",
    "category": "垂钓闲情与心境感悟",
    "grammarFocus": "动名词做主语与介词宾语 (Fishing is my favourite sport)",
    "grammarNotes": [
      "动名词 (v-ing) 兼具动词和名词特征，可做句子主语或介词宾语。",
      "be interested in doing sth（对做某事感兴趣）。"
    ],
    "dialogue": [
      {
        "speaker": "Narrator",
        "en": "Fishing is my favourite sport.",
        "zh": "钓鱼是我最喜爱的运动。"
      },
      {
        "speaker": "Narrator",
        "en": "I often fish for hours without catching anything.",
        "zh": "我经常一连钓上几个小时，却什么也没钓到。"
      },
      {
        "speaker": "Narrator",
        "en": "But this does not worry me. Some fishermen are unlucky.",
        "zh": "但这并不会让我烦恼。有些钓鱼者总是不走运。"
      },
      {
        "speaker": "Narrator",
        "en": "Instead of catching fish, they catch old boots and rubbish.",
        "zh": "他们钓不到鱼，反而钓上旧靴子和垃圾。"
      },
      {
        "speaker": "Narrator",
        "en": "I am even less lucky. I never catch anything — not even old boots.",
        "zh": "我甚至比他们还要倒霉。我什么也钓不上来——哪怕是一只旧靴子。"
      },
      {
        "speaker": "Narrator",
        "en": "After having spent whole mornings on the river, I always go home with an empty bag.",
        "zh": "在河边坐了整整一上午之后，我总是两手空空地拎着空包回家。"
      },
      {
        "speaker": "Narrator",
        "en": "'You must give up fishing!' my friends say. 'It's a waste of time.'",
        "zh": "'你必须放弃钓鱼！' 朋友们常说，'这纯粹是浪费时间。'"
      },
      {
        "speaker": "Narrator",
        "en": "But they don't realize one important thing: I am only interested in sitting in a boat and doing nothing at all!",
        "zh": "但他们没有悟出重要的一点：我唯一的兴趣，就是静静坐在小船上，什么事情都不用做！"
      }
    ],
