    "lessonNumber": 26,
    "titleEn": "The best art critics",
    "titleZh": "最佳艺术评论家",
    "unitGroup": "第二单元 (第25-48课) 复合句与复杂从句",
    "category": "现代抽象艺术与童真直觉",
    "grammarFocus": "现在完成进行时 (have been doing) 与儿童敏锐直觉",
    "grammarNotes": [
      "现在完成进行时表示过去开始且一直持续至今的动作：I have been painting for three years.",
      "tell whether... / tell right from wrong（分辨……）。"
    ],
    "dialogue": [
      {
        "speaker": "Narrator",
        "en": "I am an art student and I paint a lot of pictures.",
        "zh": "我是一名艺术学生，画过很多画。"
      },
      {
        "speaker": "Narrator",
        "en": "Many people pretend that they understand modern art.",
        "zh": "许多人总是假装自己很懂现代艺术。"
      },
      {
        "speaker": "Narrator",
        "en": "They always tell you what a picture is 'about'.",
        "zh": "他们总是好为人师地向你解释一幅画'表达的是什么'。"
      },
      {
        "speaker": "Narrator",
        "en": "Of course, many pictures are not 'about' anything. They are just pretty patterns.",
        "zh": "当然，很多抽象画根本没有具体内容，它们不过是漂亮的色彩图案而已。"
      },
      {
        "speaker": "Narrator",
        "en": "My sister Mary is only seven, but she always tells me whether my pictures are good or not.",
        "zh": "我妹妹玛丽才七岁，但她总是能一针见血地告诉我画得好不好。"
      },
      {
        "speaker": "Narrator",
        "en": "Yesterday she came into my room. 'What's that?' she asked.",
        "zh": "昨天她走进我的房间。'那是什么？' 她好奇地问。"
      },
      {
        "speaker": "Narrator",
        "en": "'It's a new picture,' I said. 'Is it good?'",
        "zh": "'这是一张新画，' 我回答，'好看吗？'"
      },
      {
        "speaker": "Mary",
        "en": "She looked at it critically. 'It's all right,' she said, 'but isn't it upside down?'",
        "zh": "她挑剔地审视着画。'还行吧，' 她说，'但你难道不是挂倒了吗？'"
      },
      {
        "speaker": "Narrator",
        "en": "I looked at it again. She was right! It was upside down!",
        "zh": "我再次抬头看那幅画。她说得完全没错！真的挂颠倒了！"
      }
    ],
